newcode='''from collections import Counter

def _runs(line):
    out = []
    i = 0
    while i < len(line):
        color = line[i]
        j = i + 1
        while j < len(line) and line[j] == color:
            j += 1
        out.append((color, i, j))
        i = j
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    candidates = []
    for color, a, b in _runs(grid[0]):
        if color == bg:
            continue
        for color2, c, d in _runs(grid[-1]):
            if color2 == color and d - c == b - a:
                candidates.append((b-a, 'h', color, (a,b), (c,d)))
    left = [grid[r][0] for r in range(h)]
    right = [grid[r][-1] for r in range(h)]
    for color, a, b in _runs(left):
        if color == bg:
            continue
        for color2, c, d in _runs(right):
            if color2 == color and d - c == b - a:
                candidates.append((b-a, 'v', color, (a,b), (c,d)))
    if not candidates:
        return [row[:] for row in grid]
    _, orient, marker, seg1, seg2 = max(candidates, key=lambda x: x[0])
    marks0 = [(r,c,grid[r][c]) for r in range(1,h-1) for c in range(1,w-1)
              if grid[r][c] not in (bg, marker)]
    if not marks0:
        return [row[:] for row in grid]
    mark_color = Counter(v for _,_,v in marks0).most_common(1)[0][0]
    marks = [(r,c) for r,c,v in marks0 if v == mark_color]
    lo1, hi1 = seg1; lo2, hi2 = seg2
    if orient == 'h':
        ix1 = sum(lo1 <= c < hi1 for _,c in marks)
        ix2 = sum(lo2 <= c < hi2 for _,c in marks)
    else:
        ix1 = sum(lo1 <= r < hi1 for r,_ in marks)
        ix2 = sum(lo2 <= r < hi2 for r,_ in marks)
    source_first = ix1 >= ix2
    src, dst = (seg1,seg2) if source_first else (seg2,seg1)
    out = [row[:] for row in grid]
    if orient == 'h' and not source_first:
        axes = {c for _,c in marks if src[0] <= c < src[1]}
        covers_segment = axes == set(range(src[0],src[1]))
        projection_end = h-1 if covers_segment else max(r for r,_ in marks)
    for r,c in marks:
        axis = c if orient == 'h' else r
        if not (src[0] <= axis < src[1]):
            continue
        projected = dst[0] + axis-src[0]
        if orient == 'h':
            if source_first:
                for rr in range(1,r): out[rr][c] = mark_color
                prange = range(0,h-1)
            else:
                for rr in range(r+1,h-1): out[rr][c] = mark_color
                prange = range(1,projection_end+1)
            for rr in prange: out[rr][projected] = mark_color
        else:
            if source_first:
                for cc in range(1,c): out[r][cc] = mark_color
                prange = range(0,w-1)
            else:
                for cc in range(c+1,w-1): out[r][cc] = mark_color
                prange = range(1,w)
            for cc in prange: out[projected][cc] = mark_color
    # Keep the guide bars and mark the original points.
    if orient == 'h':
        for c in range(seg1[0],seg1[1]): out[0][c] = marker
        for c in range(seg2[0],seg2[1]): out[h-1][c] = marker
    else:
        for r in range(seg1[0],seg1[1]): out[r][0] = marker
        for r in range(seg2[0],seg2[1]): out[r][w-1] = marker
    for r,c in marks: out[r][c] = 4
    return out
'''
